<?php use Simit\Core\Csrf; ?>
<div class="profile-grid"><aside class="panel profile-card"><?php if($profile['avatar_stored_name']):?><img class="profile-avatar profile-photo" src="/foto-profil/<?=$profile['id']?>" alt="<?=__('Foto profil','Profile photo')?>"><?php else:?><div class="profile-avatar"><?=e(strtoupper(substr($profile['name'],0,1)))?></div><?php endif;?><h2><?=e($profile['name'])?></h2><p><?=e($profile['email'])?></p><span class="badge"><?=e(ucfirst($profile['role']))?></span><?php if($profile['position']||$profile['department']):?><dl class="profile-summary"><?php if($profile['position']):?><div><dt><?=__('Jabatan','Position')?></dt><dd><?=e($profile['position'])?></dd></div><?php endif;?><?php if($profile['department']):?><div><dt><?=__('Divisi','Department')?></dt><dd><?=e($profile['department'])?></dd></div><?php endif;?></dl><?php endif;?></aside><form class="panel form-grid" method="post" action="/profil" enctype="multipart/form-data"><?=Csrf::field()?><label><?=__('Nama lengkap','Full name')?> *<input name="name" required maxlength="120" value="<?=e($profile['name'])?>"></label><label>Email *<input type="email" name="email" required maxlength="190" value="<?=e($profile['email'])?>"></label><label><?=__('ID pegawai','Employee ID')?><input name="employee_id" maxlength="80" value="<?=e($profile['employee_id']??'')?>"></label><label><?=__('Nomor telepon','Phone number')?><input name="phone" maxlength="40" value="<?=e($profile['phone']??'')?>"></label><label><?=__('Jabatan','Position')?><input name="position" maxlength="120" value="<?=e($profile['position']??'')?>"></label><label><?=__('Divisi / departemen','Division / department')?><input name="department" maxlength="120" value="<?=e($profile['department']??'')?>"></label><label><?=__('Tanggal lahir','Birth date')?><input type="date" name="birth_date" value="<?=e($profile['birth_date']??'')?>"></label><label><?=__('Foto profil','Profile photo')?><input type="file" name="avatar" accept="image/jpeg,image/png,image/webp"><small class="field-help"><?=__('JPG, PNG, atau WebP; maksimal 2 MB.','JPG, PNG, or WebP; maximum 2 MB.')?></small></label><label class="full"><?=__('Alamat','Address')?><textarea name="address" rows="3" maxlength="1000"><?=e($profile['address']??'')?></textarea></label><label class="full"><?=__('Tentang saya','About me')?><textarea name="bio" rows="4" maxlength="2000"><?=e($profile['bio']??'')?></textarea></label><label class="full"><?=__('Kata sandi baru','New password')?><input type="password" name="password" minlength="8" autocomplete="new-password"><small class="field-help"><?=__('Kosongkan jika tidak diubah.','Leave blank to keep current password.')?></small></label><div class="form-actions full"><button class="btn primary"><?=__('Simpan profil','Save profile')?></button></div></form></div>
